const areaTexts = [COMPONENTS, MAINTENANCE, QUALITY, ADMINISTRATION];
// Recognize a general purpose or definition without interpreting a particular
// operating condition. Most case questions intentionally require application.
const RECALL_NUMBERS = [
  new Set([11, 23, 29, 35, 36, 40, 46]),
  new Set([11, 15, 17, 22, 30, 34, 39, 43, 46]),
  new Set([3, 6, 8, 11, 16, 18, 25, 30, 32, 35, 42, 43, 49]),
  new Set([9, 13, 16, 18, 22, 30, 36, 46, 50, 55, 61]),
];

function parseText(text, areaIndex) {
  return text.trim().split("\n").filter(Boolean).map((line, index) => {
    const fields = line.split("|");
    if (fields.length !== 7) throw new Error(`area ${areaIndex} line ${index + 1}: expected seven fields`);
    const [question, answer, ...rest] = fields;
    const [d1, d2, d3, explanation, task] = rest;
    return { question, answer, distractors: [d1, d2, d3], explanation, task, isCalc: "no" };
  });
}

// Numeric values and formulae are computed here, rather than transcribed answer keys.
// The functions below are also independently recomputed by verify-new-questions.mjs.
function numerical(question, value, unit, wrong, explanation, task, decimals = 1) {
  const fmt = number => `${Number(number.toFixed(decimals)).toLocaleString("en-US", { maximumFractionDigits: decimals, minimumFractionDigits: decimals })} ${unit}`;
  return { question, answer: fmt(value), distractors: wrong.map(fmt), explanation: `${explanation} = ${fmt(value)}.`, task, isCalc: "yes", numericValue: value, numericDecimals: decimals, numericUnit: unit };
}

